'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),{environment}=require('./native-fixtures-20261003.cjs'),e=environment(),c=e.ctx,H=c.JYHoraryPerfection,results=[];
const start='2026-10-03T04:00:00Z',at=d=>new Date(Date.parse(start)+d*86400000).toISOString(),event=(a,b,d,angle=0)=>({a,b,angle,utc:at(d)}),pair=(a,b,angle=0)=>({a,b,angle,phase:'入相'});
function chart(positions={}){const ps={};for(const [i,k]of H?c.JYWesternDignities.KEYS.entries():[])ps[k]={key:k,longitude:40+i*45,speed:1/(i+1),retrograde:false,house:1,sign:Math.floor((40+i*45)/30)};for(const [k,p]of Object.entries(positions))ps[k]={...ps[k],...p,retrograde:p.retrograde??p.speed<0,sign:Math.floor(p.longitude/30)};return {planets:ps,essentialDignities:{dignityHosting:[]}};}
function evaluate(ch,ps,events,ingresses=[],stations=[],exact=true){const t={start,endExclusive:at(30),events:[...events,...(exact?[event(ps[0].a,ps[0].b,10,ps[0].angle)]:[])],ingresses,stations};return H.evaluate(ch,ps,t).rows[0];}
const check=(r,id)=>r.checks.find(p=>p.id===id),base=()=>chart({Mars:{longitude:10,speed:.7},Saturn:{longitude:16,speed:.03},Jupiter:{longitude:137,speed:.001}});
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
test('six separate named rule profiles, no universal yes/no event claim',()=>{const r=evaluate(base(),[pair('Mars','Saturn')],[]);assert.equal(r.checks.length,6);assert.equal(new Set(r.checks.map(p=>p.profile)).size,6);assert(r.checks.every(p=>p.scope.includes('不等於')));});
test('applicant Rx before exact is refranation; receiver Rx is not',()=>{let r=evaluate(base(),[pair('Mars','Saturn')],[],[],[{planet:'Mars',after:'retrograde',utc:at(2)}]);assert.equal(check(r,'refranation').matched,true);r=evaluate(base(),[pair('Mars','Saturn')],[],[],[{planet:'Saturn',after:'retrograde',utc:at(2)}]);assert.equal(check(r,'refranation').matched,false);});
test('station after perfection cannot retroactively deny it',()=>{const r=evaluate(base(),[pair('Mars','Saturn')],[],[],[{planet:'Mars',after:'retrograde',utc:at(11)}]);assert.equal(check(r,'refranation').matched,false);});
test('receiver sign change is evasion; applicant change is separately excluded',()=>{for(const planet of ['Saturn','Mars']){const r=evaluate(base(),[pair('Mars','Saturn')],[],[{planet,utc:at(2),direct:true}]);assert.equal(check(r,'evasion').matched,planet==='Saturn');}});
test('published Venus22Cancer/Jupiter29Taurus evasion geometry with synthetic ordered dates',()=>{const ch=chart({Venus:{longitude:112,speed:1},Jupiter:{longitude:59,speed:.1}}),r=evaluate(ch,[pair('Venus','Jupiter',60)],[event('Jupiter','Saturn',4,120)],[{planet:'Jupiter',utc:at(2),direct:true},{planet:'Venus',utc:at(7),direct:true}]);assert.equal(r.orientation.applicant,'Venus');assert.equal(check(r,'evasion').conditions.abuMasharAdditionalThirdContact,true);});
test('Lilly Sun6/Mars7/Saturn12 temporal prohibition requires third first reaching receiver',()=>{const ch=chart({Sun:{longitude:6,speed:1},Mars:{longitude:7,speed:.7},Saturn:{longitude:12,speed:.03}}),r=evaluate(ch,[pair('Mars','Saturn'),pair('Sun','Saturn'),pair('Sun','Mars')],[event('Sun','Mars',1),event('Sun','Saturn',3)]);assert.equal(check(r,'prohibition').matched,true);assert.equal(check(r,'prohibition').evidence[0].priorApplicantContacts.length,1);});
test('third contacts an unrelated planet first cannot count as first-receiver prohibition',()=>{const ch=chart({Sun:{longitude:6,speed:1},Mars:{longitude:7,speed:.7},Saturn:{longitude:12,speed:.03}}),r=evaluate(ch,[pair('Mars','Saturn'),pair('Sun','Saturn')],[event('Sun','Venus',1),event('Sun','Saturn',3)]);assert.equal(check(r,'prohibition').matched,false);});
test('Lilly Mercury10/Mars12/Jupiter13 abscission b and c retain overlap rather than duplicate votes',()=>{const ch=chart({Mercury:{longitude:10,speed:1.4},Mars:{longitude:12,speed:.7},Jupiter:{longitude:13,speed:.1}}),r=evaluate(ch,[pair('Mercury','Mars'),pair('Mars','Jupiter'),pair('Mercury','Jupiter')],[event('Mars','Jupiter',2),event('Mercury','Jupiter',3)]);const types=check(r,'abscission').evidence.map(z=>z.type);assert(types.includes('b-receiver-then-applicant-to-third'));assert(types.includes('c-applicant-first-to-third'));});
test('abscission a requires backward ingress and receiver-only contact before AB',()=>{const ch=chart({Venus:{longitude:10,speed:1},Jupiter:{longitude:20,speed:.1},Mars:{longitude:31,speed:-.2}}),r=evaluate(ch,[pair('Venus','Jupiter')],[event('Mars','Jupiter',3,90)],[{planet:'Mars',utc:at(1),direct:false}]);assert(check(r,'abscission').evidence.some(p=>p.type.startsWith('a-')));});
test('strict contrariety requires direct start, intermediate heaviness, Rx, first B then A',()=>{const ch=chart({Mars:{longitude:220,speed:.7},Saturn:{longitude:226,speed:.03},Jupiter:{longitude:137,speed:.001}}),r=evaluate(ch,[pair('Mars','Saturn')],[event('Jupiter','Saturn',2,90),event('Jupiter','Mars',3,90)],[],[{planet:'Jupiter',utc:at(1),after:'retrograde'}]);assert.equal(check(r,'contrariety').matched,true);assert.equal(check(r,'contrariety').evidence[0].daysToStation,1);assert(check(r,'contrariety').qualitativeRemaining.length);});
test('receiver-only retrograde contact does not become contrariety',()=>{const r=evaluate(base(),[pair('Mars','Saturn')],[event('Jupiter','Saturn',2,90)],[],[{planet:'Jupiter',utc:at(1),after:'retrograde'}]);assert.equal(check(r,'contrariety').matched,false);});
test('already-Rx interpositor remains outside strict direct-at-chart profile',()=>{const ch=base();ch.planets.Jupiter.speed=-.1;ch.planets.Jupiter.retrograde=true;const r=evaluate(ch,[pair('Mars','Saturn')],[event('Jupiter','Saturn',2,90),event('Jupiter','Mars',3,90)],[],[{planet:'Jupiter',utc:at(1),after:'retrograde'}]);assert.equal(check(r,'contrariety').matched,false);});
test('combust receiver return; cazimi is not automatically combustion',()=>{for(const longitude of [139,132.1]){const ch=chart({Mars:{longitude:70,speed:.7},Jupiter:{longitude:132,speed:.1},Sun:{longitude,speed:1}}),r=evaluate(ch,[pair('Mars','Jupiter',60)],[]);assert.equal(check(r,'return-of-light').matched,longitude===139);}});
test('two Rx without combustion is follower, not automatically return',()=>{const ch=chart({Venus:{longitude:40,speed:-.5},Saturn:{longitude:286,speed:-.05},Sun:{longitude:140,speed:1}}),r=evaluate(ch,[pair('Venus','Saturn',120)],[]);assert.equal(check(r,'return-of-light').matched,false);assert.equal(check(r,'return-of-light').evidence.followerException,true);});
test('missing exact within window leaves untriggered future rules undetermined',()=>{const r=evaluate(base(),[pair('Mars','Saturn')],[],[],[],false);assert(r.window.censored);assert.equal(check(r,'evasion').status,'undetermined');});
test('non-applying pair has no denial of a perfection that was not present',()=>{const out=H.evaluate(base(),[{...pair('Mars','Saturn'),phase:'出相'}],{start,endExclusive:at(30),events:[],ingresses:[],stations:[]});assert.equal(out.rows.length,0);});
test('actual Astronomy Engine horary exports all six checks with ephemeris evidence',()=>{const h=c.JYWestern.compute({utc:start,reference:start,latitude:25.03,longitude:121.56,chartPurpose:'horary',houseSystem:'R',horaryHouse:10,horaryDays:7}),d=h.horary.denialChecks;assert.equal(d.status,'calculated');assert(d.rows.length);for(const r of d.rows){assert.equal(r.checks.length,6);for(const check of r.checks)for(const v of Array.isArray(check.evidence)?check.evidence:[]){for(const ev of v.contacts||[])assert(h.horary.timeline.events.some(z=>z.utc===ev.utc&&z.a===ev.a&&z.b===ev.b));}}const n=c.JYNativeAnalysis.analyze('astro',h);assert.equal(n.horary.denialChecks.rows.length,d.rows.length);});
fs.writeFileSync('docs/horary-denials-validation-20261003.json',JSON.stringify({testedAt:new Date().toISOString(),results,syntheticRuleOrderFixtures:16,actualEphemerisFixtures:1,publishedDegreesAreIllustrativeNotHistoricalSky:'Author example positions with explicitly synthetic UTC orders; actual sky is tested separately.'},null,2));
